function smsParts(text:string){
 const basic="@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !\"#¤%&'()*+,-./0123456789:;<=>?¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà";
 const ext="^{}\\[~]|€";let units=0;let unicode=false;
 for(const char of text){if(basic.includes(char))units++;else if(ext.includes(char))units+=2;else{unicode=true;break;}}
 if(unicode){units=text.length;return units<=70?1:Math.ceil(units/67);}
 return units<=160?1:Math.ceil(units/153);
}
