 function receiveSample(){const matching=privacyRules.filter(r=>matches(r,sampleContact,sampleText));const receive=matching.filter(r=>r.when==='À la réception');if(!sampleText.trim()){notify('Saisissez un SMS fictif.');return;}const after=matching.filter(r=>r.when==='Après lecture');if(after.length>1){notify('Plusieurs règles après lecture correspondent. Désactivez le conflit avant le test.');return;}const r=after[0]||receive[0]||matching[0];setSample({contactId:sampleContact,text:sampleText,location:receive.length?'Coffre':matching.length?'Boîte protégée':'Boîte de réception',revealed:false,keep:false,ruleId:r?.id});setPrivacyLog(v=>['SMS fictif reçu : '+(receive.length?'coffre automatique':matching.length?'lecture protégée':'aucune règle'),...v].slice(0,8));notify('Réception simulée');}
