 useEffect(()=>{if(!sample?.due||sample.keep)return;const t=setTimeout(()=>finishSample(true),Math.max(0,sample.due-Date.now()));return()=>clearTimeout(t);},[sample?.due,sample?.keep,sample?.ruleId]);
 function savePrivacy(){if(!form.name?.trim()||(!form.contact&&!form.keyword?.trim())){setError('Nommez la règle et choisissez un contact ou un mot-clé.');return;}if(form.when==='À la réception'&&form.action==='Supprimer'){setError('La suppression est proposée après lecture. À la réception, choisissez le coffre.');return;}if(!form.secret?.trim()){setError('Ajoutez une phrase fictive pour la lecture protégée.');return;}const rule:PrivacyRule={id:Number(form.id)||Date.now(),name:form.name,contactId:form.contact?Number(form.contact):null,keyword:form.keyword||'',when:(form.when||'À la réception') as PrivacyRule['when'],action:(form.action||'Coffre') as PrivacyRule['action'],delay:Number(form.delay)||0,phrase:form.secret,enabled:true};setPrivacyRules(v=>[...v.filter(x=>x.id!==rule.id),rule]);setSheet('');keyboard.hide();notify('Règle de confidentialité enregistrée');}
